 "content": "def transform(grid):
    """Expand a centered 2 into a diagonal V, with spaced 1s inside it."""
    n = len(grid[0]) if grid else 0
    marker = next((c for c, value in enumerate(grid[0]) if value == 2), None) if n else None
    if marker is None:
        return [[0] * n for _ in range(n)]

    out = [[0] * n for _ in range(n)]
    for r in range(n):
        # The original color forms the two outward diagonal arms.
        for c in (marker - r, marker + r):
            if 0 <= c < n:
                out[r][c] = 2
        # Interior diagonal tracks, spaced four cells apart from row to row.
        for c in range(n):
            offset = c - marker
            if abs(offset) < r and (offset - r) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
